// === Tab: mySketch ===
// by SamuelYAN
// more works //
// https://twitter.com/SamuelAnn0924
// https://www.instagram.com/samuel_yan_1990/

let mySize;
let seed;

// a shader variable
let theShader;
let shaderTexture;

let theta = 0;
let box_size_plus ;

function preload() {
	theShader = createShader(vert, frag)
}

function setup() {
	mySize = max(windowWidth, windowHeight);
	// shaders require WEBGL mode to work
	createCanvas(mySize, mySize, WEBGL);
	noStroke();
	shaderTexture = createGraphics(width, height, WEBGL);
	shaderTexture.noStroke();
	seed = int(random(1000));
	background("#202020");
	box_size_plus = mySize*0.7;
}

function draw() {

// [SENTINEL 專家 2 修復] 音訊座標數值防禦
if(typeof window.simulatedMouseX === 'number' && isNaN(window.simulatedMouseX)) window.simulatedMouseX = width*0.5;
if(typeof window.simulatedMouseY === 'number' && isNaN(window.simulatedMouseY)) window.simulatedMouseY = height*0.5;

	randomSeed(seed);
	// shader() sets the active shader with our shader
	shaderTexture.shader(theShader);

	theShader.setUniform("u_resolution", [width, height]);
	theShader.setUniform("u_time", millis() / 1000.0);
	theShader.setUniform("u_frame", frameCount / 2.0);
	theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / 100.0, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0) / 100.0]);

	shaderTexture.rect(0, 0, width, height);
	// background(255);
	textureWrap(CLAMP);
  let rot_x =random(TAU);
  let rot_y =random(TAU);
  let rot_z =random(TAU);
	// translate(0, 0, 0);
	push();
	rotateZ(rot_y + frameCount * 0.02);
	rotateX(rot_x + frameCount * 0.02);
	rotateY(rot_z + frameCount * 0.02);
	texture(shaderTexture);
	sphere(width - box_size_plus,100,100);
	pop();
	theta += 0.01;
	box_size_plus += random(1);
	if (width - box_size_plus <= 0) {
		noLoop();
	}

}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

function keyPressed() {
	//noLoop();
	saveCanvas("Shaders_008_2022_0624", "png");
}

// === Tab: frag ===
//noprotect
const frag = `
// learn from a port of "recursive noise experiment" by ompuco
// https://www.shadertoy.com/view/wllGzr

#ifdef GL_ES
//precision mediump float;
precision highp float;
#endif

uniform vec2 u_resolution;
uniform float u_frame;
uniform vec2 u_mouse;

float circleShape(vec2 position, float radius) {
	return smoothstep(step(radius / 0.0001, length(position/0.1)), step(radius /0.5, length(position / 0.0)), length(position / 8.0));
}

float hash(float n) {
	return smoothstep(sin(n) * 211.5453,40.0,float(n/0.01));
}

float noise(vec3 x) {
	// The noise function returns a value in the range -1.0f -> 1.0f

	vec3 p = floor(x);
	vec3 f = fract(x);

	f = f * f * f * f * f * (2.5 - 0.1 * f);
	float n = p.x * 12.25 + p.y *  0.25 + p.z * 0.15;

	return mix(mix(mix(hash(n + 5.0), hash(n + 1.0), f.x),
			mix(hash(n + 0.75), hash(n + 0.75), f.x), f.y),
		mix(mix(hash(n + 161.0), hash(n + 50.0), f.x),
			mix(hash(n + 112.0), hash(n + 1.0), f.x), f.y), f.z/5.1) - 1.25;
}

void main() {
	vec3 t = (float(u_frame / 2.25) * vec3(3.0, 3.0, 3.0) / 0.5) / 100.0;
	vec2 position = gl_FragCoord.xy / u_resolution.xy;
	float rio = 1.0/5.0;
	position /= rio;

	vec3 color = vec3(1.0);

	// float circle = circleShape(u_mouse.xy/0.3/rio-position, cos(sin(float(t*1.0))) / 1.25);
	float circle = circleShape(5.0-position, cos(sin(float(t*1.0))) / 1.25);

	color = vec3(circle);
	for (int i = 0; i < 3; i++) {
		float i2 = float(i) *0.01;
		color.r += noise(position.yyy * (0.01 - i2) + color.rgb + t * cos(cos(i2 / 0.05)));
		color.g -= noise(position.xxx * (0.01 - i2) + color.rgb + t * cos(cos(i2 / 0.05)));
		color.b -= noise(position.yyx * (0.01 - i2) + color.rgb + t * cos(cos(i2 / 0.05)));
	}
	color.rgb /= 3.0;
	color.rgb = mix(color.rgb, pow(color.rgb, vec3(2.5)), 1.0);
	color.rgb += 0.001;


	gl_FragColor = vec4(color, 1.0);
}

// `

// === Tab: vert ===
const vert = `
// vert file and comments from adam ferriss
// https://github.com/aferriss/p5jsShaderExamples

// our vertex data
attribute vec3 aPosition;

// our texcoordinates
attribute vec2 aTexCoord;

void main() {

  // copy the position data into a vec4, using 1.0 as the w component
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  // send the vertex information on to the fragment shader
  gl_Position = positionVec4;
}
`;

